private bool _last _delaysInterrupt = false;

// Add property
public bool LastOpcodeDelaysInterrupt => _lastOpcodeDelaysInterrupt;

// In ExecuteInstruction - when handling branches
if (taken && !pageCross) {
    _lastOpcodeDelaysInterrupt = true;
    _branchTargetFetchPending = true;
}

// In Is InstructionBoundary - when we complete an instruction
if (boundary) {
    _lastOpcodeDelaysInterrupt = false; // reset after instruction completes
